{"python":"import re
file='TCA-14-2591-s001.xlsx'
sheet='工作表1'
rows=get_rows(file,sheet)
score_map={
 'E+C+':1,'E+C-':1,'E-C+':0,'E-C-':0,
 'E+C−':1,'E−C+':0,'E−C−':0
}
truth_map={'CR':1,'PR':1,'SD':1,'PD':0}
records=[]
patient=None
for i,row in enumerate(rows[1:], start=2):
    if len(row)>1 and row[1] not in (None,''):
        patient=row[1]
    draw=row[6] if len(row)>6 else ''
    # (timing label, comparison column 0-based, response column 0-based, spreadsheet column)
    for timing,cidx,ridx,col in [('retrospective',12,10,'M'),('prospective',13,11,'N')]:
        comp=row[cidx] if len(row)>cidx else ''
        resp=row[ridx] if len(row)>ridx else ''
        if isinstance(comp,str) and re.match(r'^E[+\-−]C[+\-−]$', comp.strip()):
            comp_ref=f'{file}/{sheet}/{col}{i}'
            resp_col='K' if timing=='retrospective' else 'L'
            resp_ref=f'{file}/{sheet}/{resp_col}{i}'
            records.append({
                'id':f'P{patient}_draw{draw}_{timing}',
                'score':{'ref':comp_ref,'map':score_map},
                'truth':{'ref':resp_ref,'map':truth_map}
            })
positives=[r for r in records if r['truth']['ref']]
# Independent validation from source labels
true_positive=0
clinical_positive=0
for row in rows[1:]:
    for cidx in (12,13):
        comp=row[cidx] if len(row)>cidx else ''
        if isinstance(comp,str):
            m=re.match(r'^E([+\-−])C([+\-−])$',comp.strip())
            if m:
                if m.group(2)=='+':
                    clinical_positive+=1
                    if m.group(1)=='+': true_positive+=1
sens=true_positive/clinical_positive
assert len(records)==14, (len(records), true_positive, clinical_positive)
assert clinical_positive==9 and true_positive==9 and abs(sens-1.0)<1e-12
